def gen(rng):
    def build(n, parents, wlo, whi, nq, deep_bias=False):
        # parents[i] for i in 2..n are labels in 1..i-1 (node 1 is the root); relabel 2..n randomly
        perm = list(range(2, n + 1))
        rng.shuffle(perm)
        lab = {1: 1}
        for i in range(2, n + 1):
            lab[i] = perm[i - 2]
        edges = []
        for i in range(2, n + 1):
            a, b = lab[i], lab[parents[i]]
            if rng.random() < 0.5:
                a, b = b, a
            edges.append((a, b, rng.randint(wlo, whi)))
        rng.shuffle(edges)
        qs = []
        for _ in range(nq):
            if deep_bias and rng.random() < 0.7:
                u = lab[rng.randint(max(2, n - n // 8), n)]
                v = lab[rng.randint(max(2, n - n // 8), n)]
            else:
                u = rng.randint(1, n)
                v = rng.randint(1, n)
            qs.append((u, v))
        lines = [str(n)] + [f'{a} {b} {w}' for a, b, w in edges] + [str(nq)] + [f'{u} {v}' for u, v in qs]
        return '\n'.join(lines)

    def random_parents(n, window=None):
        par = {}
        for i in range(2, n + 1):
            lo = 1 if window is None else max(1, i - window)
            par[i] = rng.randint(lo, i - 1)
        return par

    def capped_chain(n, cap):
        # follow the previous node until depth cap, then attach to a random shallow node
        par = {}
        depth = {1: 0}
        for i in range(2, n + 1):
            if depth[i - 1] < cap:
                par[i] = i - 1
            else:
                par[i] = rng.randint(1, i - 1)
                while depth[par[i]] > cap - 1:
                    par[i] = rng.randint(1, i - 1)
            depth[i] = depth[par[i]] + 1
        return par

    tests = []
    tests.append('3\n1 2 3\n1 3 2\n1\n2 3')
    tests.append('2\n1 2 25\n3\n1 2\n2 1\n1 1')
    tests.append('4\n1 2 5\n2 3 5\n3 4 5\n3\n1 4\n2 2\n4 3')
    tests.append('5\n1 2 1\n1 3 25\n1 4 1\n1 5 25\n4\n2 3\n2 4\n3 5\n2 5')
    for _ in range(14):
        n = rng.randint(2, 14)
        shape = rng.choice([0, 1, 2])
        par = random_parents(n, None if shape == 0 else (1 if shape == 1 else 2))
        wlo, whi = rng.choice([(1, 25), (1, 3), (10, 12), (1, 25)])
        tests.append(build(n, par, wlo, whi, rng.randint(1, 12)))
    N = 50000
    Q = 50000
    tests.append(build(N, random_parents(N), 1, 25, Q))
    tests.append(build(N, capped_chain(N, 2400), 1, 25, Q, True))
    tests.append(build(N, capped_chain(N, 60), 1, 25, Q, True))
    tests.append(build(N, {i: 1 for i in range(2, N + 1)}, 1, 25, Q))
    tests.append(build(N, capped_chain(N, 2400), 1, 3, Q, True))
    tests.append(build(10000, capped_chain(10000, 2400), 1, 25, 10000, True))
    return tests
